"""
Tests for the Stripe webhook endpoint.

Run with:
    python -m pytest test_webhook.py -v
"""

import json
import time

import pytest
import stripe

from webhook import app, handle_payment_succeeded, handle_payment_failed


@pytest.fixture()
def client():
    app.config["TESTING"] = True
    app.config["PROCESSED_EVENTS"] = set()
    return app.test_client()


def _sign_payload(payload: bytes, secret: str) -> str:
    """Build a Stripe-Signature header for the given payload."""
    timestamp = int(time.time())
    signed_payload = f"{timestamp}.{payload.decode()}".encode()
    signature = stripe.WebhookSignature._compute_signature(
        signed_payload, secret
    )
    return (
        f"t={timestamp},v1={signature},"
        f"v0={stripe.WebhookSignature._compute_signature(signed_payload, 'x')}"
    )


def _make_event(event_type: str, payment_intent: dict) -> dict:
    return {
        "id": f"evt_test_{event_type}",
        "object": "event",
        "type": event_type,
        "data": {"object": payment_intent},
    }


def test_health(client):
    resp = client.get("/health")
    assert resp.status_code == 200


def test_missing_signature_header(client):
    resp = client.post("/webhook", data=b"{}")
    assert resp.status_code == 400
    assert resp.get_json()["error"] == "Missing Stripe-Signature header"


def test_invalid_signature(client):
    resp = client.post(
        "/webhook",
        data=b"{}",
        headers={"Stripe-Signature": "t=1,v1=invalid"},
    )
    assert resp.status_code == 400
    assert resp.get_json()["error"] == "Invalid signature"


def test_payment_intent_succeeded(client):
    payload = json.dumps(_make_event("payment_intent.succeeded", {
        "id": "pi_123",
        "customer": "cus_123",
        "amount": 2000,
        "currency": "usd",
        "metadata": {"order_id": "order_123"},
    })).encode()
    headers = {"Stripe-Signature": _sign_payload(payload, "whsec_test")}

    resp = client.post("/webhook", data=payload, headers=headers)
    assert resp.status_code == 200
    assert resp.get_json()["status"] == "received"

    # Duplicate delivery is acknowledged but not processed again.
    resp = client.post("/webhook", data=payload, headers=headers)
    assert resp.status_code == 200
    assert resp.get_json()["status"] == "duplicate"


def test_payment_intent_failed(client):
    payload = json.dumps(_make_event("payment_intent.payment_failed", {
        "id": "pi_456",
        "customer": "cus_456",
        "metadata": {"order_id": "order_456"},
        "last_payment_error": {
            "code": "card_declined",
            "message": "Your card was declined.",
        },
    })).encode()
    headers = {"Stripe-Signature": _sign_payload(payload, "whsec_test")}

    resp = client.post("/webhook", data=payload, headers=headers)
    assert resp.status_code == 200
    assert resp.get_json()["status"] == "received"


def test_unhandled_event_acknowledged(client):
    payload = json.dumps(_make_event("charge.refunded", {
        "id": "ch_123",
    })).encode()
    headers = {"Stripe-Signature": _sign_payload(payload, "whsec_test")}

    resp = client.post("/webhook", data=payload, headers=headers)
    assert resp.status_code == 200
    assert resp.get_json()["status"] == "received"


def test_handler_functions_run_without_error(capsys):
    assert handle_payment_succeeded({
        "id": "pi_1", "customer": "cus_1", "amount": 100, "currency": "usd"
    }) is True
    assert handle_payment_failed({
        "id": "pi_2",
        "customer": "cus_2",
        "last_payment_error": {"message": "card_declined"},
    }) is True

