"""Tests for the Stripe webhook endpoint (run with `python -m pytest -v`)."""

import json
import time

import pytest
import stripe

from webhook import app


@pytest.fixture()
def client():
    app.config["TESTING"] = True
    app.config["PROCESSED_EVENTS"] = set()
    return app.test_client()


def _sign(payload: bytes, secret: str) -> str:
    ts = int(time.time())
    signed = f"{ts}.{payload.decode()}".encode()
    sig = stripe.WebhookSignature._compute_signature(signed, secret)
    return f"t={ts},v1={sig}"


def _event(event_type: str, pi: dict) -> dict:
    return {"id": f"evt_{event_type}", "object": "event",
            "type": event_type, "data": {"object": pi}}


def test_missing_signature(client):
    assert client.post("/webhook", data=b"{}").status_code == 400


def test_invalid_signature(client):
    r = client.post("/webhook", data=b"{}",
                    headers={"Stripe-Signature": "t=1,v1=bad"})
    assert r.status_code == 400


def test_succeeded(client):
    payload = json.dumps(_event("payment_intent.succeeded", {
        "id": "pi_1", "customer": "cus_1", "amount": 2000,
        "currency": "usd", "metadata": {"order_id": "o1"},
    })).encode()
    h = {"Stripe-Signature": _sign(payload, "whsec_test")}
    assert client.post("/webhook", data=payload, headers=h).status_code == 200
    # duplicate
    assert client.post("/webhook", data=payload, headers=h).get_json()["status"] == "duplicate"


def test_failed(client):
    payload = json.dumps(_event("payment_intent.payment_failed", {
        "id": "pi_2", "customer": "cus_2",
        "last_payment_error": {"code": "card_declined", "message": "declined"},
    })).encode()
    h = {"Stripe-Signature": _sign(payload, "whsec_test")}
    assert client.post("/webhook", data=payload, headers=h).status_code == 200
